import React from "react";
import {
  LayoutDashboard,
  List,
  BarChart3,
  Smartphone,
  DollarSign,
} from "lucide-react";
import { PageId, UserProfile } from "../types";

interface SidebarProps {
  currentPage: PageId;
  onNavigate: (page: PageId) => void;
  user: UserProfile;
}

interface NavItem {
  id: PageId;
  label: string;
  icon: React.ReactNode;
}

const NAV_ITEMS: NavItem[] = [
  { id: "dashboard", label: "Dashboard", icon: <LayoutDashboard size={18} /> },
  { id: "transactions", label: "Transactions", icon: <List size={18} /> },
  { id: "analytics", label: "Analytics", icon: <BarChart3 size={18} /> },
  { id: "mobile", label: "Mobile Preview", icon: <Smartphone size={18} /> },
];

const Sidebar: React.FC<SidebarProps> = ({ currentPage, onNavigate, user }) => (
  <aside className="hidden md:flex flex-col w-56 shrink-0 bg-white border-r border-gray-100 h-screen sticky top-0 py-6 px-3 gap-1">
    {/* Logo */}
    <div className="flex items-center gap-2 px-3 pb-6">
      <DollarSign size={22} className="text-emerald-500" />
      <span className="text-lg font-medium">
        <span className="text-emerald-500">Spend</span>Wise
      </span>
    </div>

    {/* Nav items */}
    {NAV_ITEMS.map((item) => (
      <button
        key={item.id}
        onClick={() => onNavigate(item.id)}
        className={`flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm font-medium transition-colors text-left w-full ${
          currentPage === item.id
            ? "bg-emerald-50 text-emerald-700"
            : "text-gray-500 hover:bg-gray-50 hover:text-gray-800"
        }`}
      >
        <span
          className={currentPage === item.id ? "text-emerald-600" : "text-gray-400"}
        >
          {item.icon}
        </span>
        {item.label}
      </button>
    ))}

    {/* User footer */}
    <div className="mt-auto pt-4 border-t border-gray-100">
      <div className="flex items-center gap-3 px-3 py-2">
        <div className="w-8 h-8 rounded-full bg-emerald-100 flex items-center justify-center text-xs font-semibold text-emerald-700 shrink-0">
          {user.initials}
        </div>
        <div className="min-w-0">
          <p className="text-sm font-medium truncate">{user.name}</p>
          <p className="text-xs text-gray-400">{user.plan}</p>
        </div>
      </div>
    </div>
  </aside>
);

export default Sidebar;
